code='''def transform(grid):
    g=[row[:] for row in grid]
    bg=max(set(v for row in g for v in row), key=lambda v: sum(row.count(v) for row in g))
    pat=None
    for row in g:
        runs=[]; cur=[]
        for c,v in enumerate(row):
            if v!=bg: cur.append(v)
            elif cur:
                runs.append(cur); cur=[]
        if cur: runs.append(cur)
        candidates=[x for x in runs if len(x)>1]
        if candidates: pat=max(candidates,key=len); break
    if pat is None:return g
    for r,row in enumerate(g):
        for c,v in enumerate(row):
            if v!=bg and v not in pat:
                start=c-len(pat)//2
                for i,x in enumerate(pat):
                    if 0<=start+i<len(row): g[r][start+i]=x
    return g
'''
